def _key_body_inventory():
    rows = json.loads(zlib.decompress(base64.b85decode(_KEY_BODY_PAYLOAD)).decode("utf-8"))
    decoded = []
    for group, case, rel, content, expected in rows:
        if isinstance(content, dict):
            content = base64.b85decode(content["bytes"])
        decoded.append((group, case, rel, content, expected))
    if len(decoded) != 126 or len({(group, case) for group, case, *_ in decoded}) != 126:
        raise SystemExit("goal433-attack: REFUSED [inventory]")
    return tuple(decoded)


def _non_key_ledger(repo, origin_owner):
    contract = (repo / "tools" / "leak_scan.py").read_text(encoding="utf-8")
    if len(_NON_KEY_LEDGER) != 21 or len({row[0] for row in _NON_KEY_LEDGER}) != 21:
        raise SystemExit("goal433-attack: REFUSED [non-key-ledger]")
    if any(disposition not in {"fixed-red", "documented-oos"}
           or (disposition == "fixed-red") != bool(expected)
           for _, disposition, _boundary, _rel, _content, expected in _NON_KEY_LEDGER):
        raise SystemExit("goal433-attack: REFUSED [non-key-ledger]")
    if any(boundary not in contract for _, disposition, boundary, *_ in _NON_KEY_LEDGER
           if disposition == "documented-oos"):
        raise SystemExit("goal433-attack: REFUSED [oos-boundary]")
    return tuple((case, disposition, boundary, rel, content.replace("{origin_owner}", origin_owner), expected)
                 for case, disposition, boundary, rel, content, expected in _NON_KEY_LEDGER)


def _findings(stdout):
    found = {}
    for line in stdout.splitlines():
        parts = line.rsplit(": ", 1)
        if len(parts) != 2:
            continue
        path_line, rule = parts
        path, sep, number = path_line.rpartition(":")
        if sep and number.isdigit():
            found.setdefault(path, []).append("%s: %s" % (number, rule))
    return found


def _implementation_fingerprint(repo):
    """Identify the exact scanner and harness bytes used by an uncommitted evidence run."""
    digest = hashlib.sha256()
    for rel in ("tools/leak_scan.py", "skills/sigma-loop/scripts/scrub.py"):
        data = (repo / rel).read_bytes()
        digest.update(rel.encode("utf-8") + b"\0" + data + b"\0")
    digest.update(b"tools/goal433_attack.py\0" + pathlib.Path(__file__).read_bytes() + b"\0")
    return digest.hexdigest()


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", required=True); ap.add_argument("--origin-owner", required=True)
    ap.add_argument("--allowed-public-slug", required=True); ap.add_argument("--json-out", required=True)
    ns = ap.parse_args(argv)
    repo = pathlib.Path(ns.repo).resolve()
    output = (repo / ns.json_out).resolve()
    scanner = repo / "tools" / "leak_scan.py"
    if not scanner.is_file() or repo not in output.parents or output == repo:
        raise SystemExit("goal433-attack: REFUSED [paths]")
    owner, sep, public_name = ns.allowed_public_slug.partition("/")
    if not sep or not owner or not public_name or owner.lower() != ns.origin_owner.lower():
        raise SystemExit("goal433-attack: REFUSED [allowed-public-slug]")
    origin = _run(["git", "-C", str(repo), "remote", "get-url", "origin"])
    if origin.returncode or ("github.com/" + ns.origin_owner.lower() + "/") not in origin.stdout.lower():
        raise SystemExit("goal433-attack: REFUSED [origin-owner]")
    head = _run(["git", "-C", str(repo), "rev-parse", "HEAD"]).stdout.strip()
    implementation = _implementation_fingerprint(repo)
    inventory = _key_body_inventory()
    non_key = _non_key_ledger(repo, ns.origin_owner)
    # The test inventory imports its own scanner helpers.  Rebind the source after that import so
    # this harness always copies the requested checkout's scanner, never a helper's scratch path.
    scanner = repo / "tools" / "leak_scan.py"
    scanner_bytes = scanner.read_bytes()
    scrub_bytes = (repo / "skills/sigma-loop/scripts/scrub.py").read_bytes()
    results = []
    with tempfile.TemporaryDirectory(dir=str(repo), prefix="goal433-") as temp:
        scratch = pathlib.Path(temp)
        _run(["git", "init", "-q"], scratch)
        _run(["git", "remote", "add", "origin", "https://github.com/%s/demo.git" % ns.origin_owner], scratch)
        gate = scratch / "tools" / "leak_scan.py"
        gate.parent.mkdir(parents=True, exist_ok=True)
        gate.write_bytes(scanner_bytes)
        scrub = scratch / "skills/sigma-loop/scripts/scrub.py"
        scrub.parent.mkdir(parents=True, exist_ok=True)
        scrub.write_bytes(scrub_bytes)
        doctor = scratch / "skills/sigma-doctor/scripts/doctor.py"
        doctor.parent.mkdir(parents=True, exist_ok=True)
        doctor.write_text('_MARKETPLACE_REPO = %r\n' % ns.allowed_public_slug, encoding="utf-8")
        (scratch / "allowed-public.md").write_text(
            "https://github.com/%s\n" % ns.allowed_public_slug, encoding="utf-8")
        for _group, _case, rel, content, _expected in inventory:
            target = scratch / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            if isinstance(content, bytes):
                target.write_bytes(content)
            else:
                target.write_text("line one\n" + content + "\n", encoding="utf-8")
        for _case, _disposition, _boundary, rel, content, _expected in non_key:
            target = scratch / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(content + "\n", encoding="utf-8")
        _run(["git", "add", "-A"], scratch)
        proc = _run([sys.executable, "tools/leak_scan.py"], scratch)
        found = _findings(proc.stdout)
        if found.get("allowed-public.md"):
            raise SystemExit("goal433-attack: FAILED [allowed-public-slug]")
        for group, case, rel, _content, expected in inventory:
            wanted_rules = {item.split(": ", 1)[1] for item in expected}
            observed = sorted(item for item in found.get(rel, [])
                              if not wanted_rules or item.split(": ", 1)[1] in wanted_rules)
            classification = "fixed-red" if expected else "clean-control"
            outcome = "red" if observed == sorted(expected) and expected else "clean" if not observed and not expected else "unexpected"
            results.append({"id": "%s/%s" % (group, case), "path": rel, "expected": expected,
                            "observed": observed, "classification": classification, "outcome": outcome})
        for case, disposition, boundary, rel, _content, expected in non_key:
            observed = sorted(found.get(rel, []))
            expected_observed = [item[len(rel) + 2:] for item in expected]
            outcome = ("red" if expected and observed == expected_observed else
                       "clean" if not expected and not observed else "unexpected")
            results.append({"id": case, "path": rel, "expected": expected, "observed": observed,
                            "classification": disposition, "boundary": boundary, "outcome": outcome})
    unexpected = [row["id"] for row in results if row["outcome"] == "unexpected"]
    if unexpected:
        raise SystemExit("goal433-attack: FAILED [unexpected:%s]" % ",".join(unexpected))
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps({"schema": "sigma.goal433-attack/v3", "base_revision": head,
                                  "origin_owner": ns.origin_owner,
                                  "implementation_sha256": implementation,
                                  "allowed_public_slug": ns.allowed_public_slug,
                                  "invocation": "python3 tools/goal433_attack.py --repo . --origin-owner <owner> --allowed-public-slug <slug> --json-out " + str(output.relative_to(repo)), "cases": results, "totals": {"attempts": len(results), "unclassified": 0}}, indent=2) + "\n")


if __name__ == "__main__":
    main()
